// Syscall numbers for Linux x86_64
pub const SYS_READ: u64 = 0;
pub const SYS_WRITE: u64 = 1;
pub const SYS_POLL: u64 = 7;
pub const SYS_BRK: u64 = 12;
pub const SYS_EXIT: u64 = 60;
pub const SYS_ARCH_PRCTL: u64 = 158;

// arch_prctl commands
pub const ARCH_SET_FS: u64 = 0x1002;
pub const ARCH_GET_FS: u64 = 0x1003;

//! Memory allocation (malloc, free, etc.)

use crate::syscall::{syscall1, SYS_BRK};

// Heap state
static mut HEAP_START: *mut u8 = core::ptr::null_mut();
static mut HEAP_END: *mut u8 = core::ptr::null_mut();
static mut HEAP_CURRENT: *mut u8 = core::ptr::null_mut();

fn brk(addr: *mut u8) -> *mut u8 {
    unsafe { syscall1(SYS_BRK, addr as u64) as *mut u8 }
}

pub fn init_heap() {
    unsafe {
        HEAP_START = brk(core::ptr::null_mut());
        HEAP_END = HEAP_START;
        HEAP_CURRENT = HEAP_START;
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn malloc(size: usize) -> *mut u8 {
    unsafe {
        let aligned_size = (size + 15) & !15;
        let new_current = HEAP_CURRENT.add(aligned_size);

        if new_current > HEAP_END {
            let grow_size = (aligned_size + 4095) & !4095;
            let new_end = brk(HEAP_END.add(grow_size));
            if new_end <= HEAP_END {
                return core::ptr::null_mut();
            }
            HEAP_END = new_end;
        }

        let ptr = HEAP_CURRENT;
        HEAP_CURRENT = new_current;
        ptr
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn realloc(ptr: *mut u8, size: usize) -> *mut u8 {
    if ptr.is_null() {
        return malloc(size);
    }
    let new_ptr = malloc(size);
    if !new_ptr.is_null() {
        unsafe {
            core::ptr::copy_nonoverlapping(ptr, new_ptr, size);
        }
    }
    new_ptr
}

#[unsafe(no_mangle)]
pub extern "C" fn calloc(nmemb: usize, size: usize) -> *mut u8 {
    let total = nmemb.saturating_mul(size);
    let ptr = malloc(total);
    if !ptr.is_null() {
        unsafe {
            core::ptr::write_bytes(ptr, 0, total);
        }
    }
    ptr
}

#[unsafe(no_mangle)]
pub extern "C" fn free(_ptr: *mut u8) {
    // Bump allocator doesn't free individual allocations
}

#[unsafe(no_mangle)]
pub extern "C" fn posix_memalign(memptr: *mut *mut u8, alignment: usize, size: usize) -> i32 {
    // Simple implementation: over-allocate and align
    if !alignment.is_power_of_two() || alignment < core::mem::size_of::<*mut u8>() {
        return 22; // EINVAL
    }
    let ptr = malloc(size + alignment);
    if ptr.is_null() {
        return 12; // ENOMEM
    }
    let aligned = ((ptr as usize + alignment - 1) & !(alignment - 1)) as *mut u8;
    unsafe {
        *memptr = aligned;
    }
    0
}

// Memory operations needed by std
#[unsafe(no_mangle)]
pub extern "C" fn memcpy(dest: *mut u8, src: *const u8, n: usize) -> *mut u8 {
    unsafe {
        core::ptr::copy_nonoverlapping(src, dest, n);
    }
    dest
}

#[unsafe(no_mangle)]
pub extern "C" fn memmove(dest: *mut u8, src: *const u8, n: usize) -> *mut u8 {
    unsafe {
        core::ptr::copy(src, dest, n);
    }
    dest
}

#[unsafe(no_mangle)]
pub extern "C" fn memset(dest: *mut u8, c: i32, n: usize) -> *mut u8 {
    unsafe {
        core::ptr::write_bytes(dest, c as u8, n);
    }
    dest
}

#[unsafe(no_mangle)]
pub extern "C" fn memcmp(s1: *const u8, s2: *const u8, n: usize) -> i32 {
    for i in 0..n {
        let a = unsafe { *s1.add(i) };
        let b = unsafe { *s2.add(i) };
        if a != b {
            return a as i32 - b as i32;
        }
    }
    0
}

#[unsafe(no_mangle)]
pub extern "C" fn bcmp(s1: *const u8, s2: *const u8, n: usize) -> i32 {
    memcmp(s1, s2, n)
}

//! I/O operations (read, write, etc.)

use crate::syscall::{syscall3, SYS_READ, SYS_WRITE};

#[unsafe(no_mangle)]
pub extern "C" fn read(fd: i32, buf: *mut u8, count: usize) -> isize {
    unsafe { syscall3(SYS_READ, fd as u64, buf as u64, count as u64) as isize }
}

#[unsafe(no_mangle)]
pub extern "C" fn write(fd: i32, buf: *const u8, count: usize) -> isize {
    unsafe { syscall3(SYS_WRITE, fd as u64, buf as u64, count as u64) as isize }
}

#[unsafe(no_mangle)]
pub extern "C" fn writev(_fd: i32, _iov: *const u8, _iovcnt: i32) -> isize {
    // TODO: implement properly
    -1
}

//! Process management (_start, exit, __libc_start_main)

use crate::memory::init_heap;
use crate::syscall::{syscall1, SYS_EXIT};
use crate::thread::init_tls;

/// Exit the process with the given code
pub fn exit(code: i32) -> ! {
    unsafe {
        syscall1(SYS_EXIT, code as u64);
    }
    loop {}
}

/// C-compatible abort
#[unsafe(no_mangle)]
pub extern "C" fn abort() -> ! {
    exit(134) // 128 + SIGABRT(6)
}

// External reference to the C ABI main that rustc generates
unsafe extern "C" {
    fn main(argc: i32, argv: *const *const u8, envp: *const *const u8) -> i32;
}

/// The libc entry point called by _start
#[unsafe(no_mangle)]
pub extern "C" fn __libc_start_main(
    main_fn: extern "C" fn(i32, *const *const u8, *const *const u8) -> i32,
    argc: i32,
    argv: *const *const u8,
    _init: usize,
    _fini: usize,
    _rtld_fini: usize,
    _stack_end: *mut u8,
) -> ! {
    // Initialize TLS before anything else
    init_tls();

    // Initialize heap
    init_heap();

    // Calculate envp (follows argv + NULL terminator)
    let envp = unsafe { argv.offset(argc as isize + 1) };

    // Call main and exit with its return value
    let ret = main_fn(argc, argv, envp);
    exit(ret)
}

/// Program entry point - called by the kernel
#[unsafe(no_mangle)]
#[unsafe(naked)]
pub extern "C" fn _start() -> ! {
    // Kernel enters with RSP pointing to argc on the stack
    // Stack layout: [argc] [argv[0]] [argv[1]] ... [NULL] [envp[0]] ...
    //
    // We need to call __libc_start_main(main, argc, argv, init, fini, rtld_fini, stack_end)
    core::arch::naked_asm!(
        "xor rbp, rbp",              // Clear frame pointer (ABI requirement)
        "lea rdi, [{main}]",         // arg1: main function address
        "mov rsi, [rsp]",            // arg2: argc
        "lea rdx, [rsp + 8]",        // arg3: argv
        "xor rcx, rcx",              // arg4: init (NULL)
        "xor r8, r8",                // arg5: fini (NULL)
        "xor r9, r9",                // arg6: rtld_fini (NULL)
        "push rsp",                  // arg7: stack_end (on stack)
        "and rsp, -16",              // Align stack to 16 bytes
        "call __libc_start_main",
        "ud2",                       // Should never return
        main = sym main,
    );
}

//! Thread-local storage and pthread stubs

use crate::memory::malloc;
use crate::syscall::{syscall2, SYS_ARCH_PRCTL, SYS_POLL, syscall3, ARCH_SET_FS};

/// Initialize Thread-Local Storage
/// 
/// This sets up the FS segment register to point to a TLS block.
/// Must be called before any code that uses #[thread_local] statics.
pub fn init_tls() {
    // For now, allocate a minimal TLS block
    // The PT_TLS segment tells us the real size needed (24 bytes for our binary)
    // We allocate: [TLS data (24 bytes)] [self-pointer (8 bytes)]
    //                                     ^-- FS.base points here

    const TLS_SIZE: usize = 64;  // Over-allocate to be safe
    const SELF_PTR_SIZE: usize = 8;

    unsafe {
        let block = malloc(TLS_SIZE + SELF_PTR_SIZE);
        if block.is_null() {
            // Can't do much without memory
            return;
        }

        // Zero-initialize the TLS block
        core::ptr::write_bytes(block, 0, TLS_SIZE + SELF_PTR_SIZE);

        // The self-pointer goes at the end, and FS.base points to it
        let tcb = block.add(TLS_SIZE) as *mut usize;
        *tcb = tcb as usize;

        // Set FS.base to point at the self-pointer (TCB)
        syscall2(SYS_ARCH_PRCTL, ARCH_SET_FS, tcb as u64);
    }
}

// --- pthread stubs ---

#[unsafe(no_mangle)]
pub extern "C" fn pthread_self() -> usize {
    1  // Return constant thread ID for main thread
}

#[unsafe(no_mangle)]
pub extern "C" fn pthread_getattr_np(_thread: usize, _attr: *mut u8) -> i32 {
