        *stacksize = 8 * 1024 * 1024;  // 8MB stack
    }
    0
}

#[unsafe(no_mangle)]
pub extern "C" fn pthread_attr_getguardsize(_attr: *const u8, guardsize: *mut usize) -> i32 {
