// --- poll (needed by std at startup) ---

#[repr(C)]
pub struct pollfd {
    pub fd: i32,
    pub events: i16,
    pub revents: i16,
}

#[unsafe(no_mangle)]
pub extern "C" fn poll(fds: *mut pollfd, nfds: u64, timeout: i32) -> i32 {
    unsafe { syscall3(SYS_POLL, fds as u64, nfds, timeout as u64) as i32 }
}

// --- sysconf ---

const _SC_PAGESIZE: i32 = 30;
const _SC_NPROCESSORS_ONLN: i32 = 84;

#[unsafe(no_mangle)]
pub extern "C" fn sysconf(name: i32) -> i64 {
    match name {
        _SC_PAGESIZE => 4096,
        _SC_NPROCESSORS_ONLN => 1,
        _ => -1,
    }
}

//! Signal handling stubs

const SIG_DFL: usize = 0;

#[unsafe(no_mangle)]
pub extern "C" fn signal(_signum: i32, _handler: usize) -> usize {
    SIG_DFL  // Return previous handler (pretend it was default)
