//! errno support

static mut ERRNO: i32 = 0;

#[unsafe(no_mangle)]
pub extern "C" fn __errno_location() -> *mut i32 {
    core::ptr::addr_of_mut!(ERRNO)
}

#[unsafe(no_mangle)]
pub extern "C" fn __xpg_strerror_r(_errnum: i32, _buf: *mut u8, _buflen: usize) -> i32 {
    // TODO: implement properly
    -1
